+        self.generate(node, 1)
+        psbt = node.createpsbt(inputs=[{"txid": txid, "vout": 0}], outputs=[])
+
+        blk_dat = node.blocks_path / "blk00000.dat"
+        blk_dat_moved = node.blocks_path / "blk00000.dat.moved"
+        blk_dat.rename(blk_dat_moved)
+
